"""Authored intersection parking probes. CPU geometry is not Native observation."""
from __future__ import annotations
import json
import math
from pathlib import Path
import xml.etree.ElementTree as ET

HERE = Path(__file__).resolve().parent
INTERSECTION = (-7.0, -7.0, 7.0, 7.0)
BODY_LENGTH_M = 5.2
BODY_WIDTH_M = 2.2
STOP_X = {"probe_a": -13.0, "probe_b": 0.0}
START_X = -50.0
STEP_M = 0.1


def road_xml() -> str:
    return (HERE / "road.xodr").read_text()


def body(x: float, y: float = -1.75) -> list[list[float]]:
    return [[round(x + dx, 5), round(y + dy, 5)] for dx, dy in
            ((-2.6, -1.1), (-2.6, 1.1), (2.6, 1.1), (2.6, -1.1))]


def route(suffix: str) -> list[list[float]]:
    if suffix not in STOP_X:
        raise ValueError("Unknown parking probe")
    n = round((STOP_X[suffix] - START_X) / STEP_M)
    return [[round(START_X + i * STEP_M, 5), -1.75] for i in range(n + 1)]


def overlap_area_xy(vertices: list[list[float]]) -> float:
    xs = [v[0] for v in vertices]
    ys = [v[1] for v in vertices]
    x = max(0.0, min(max(xs), INTERSECTION[2]) - max(min(xs), INTERSECTION[0]))
    y = max(0.0, min(max(ys), INTERSECTION[3]) - max(min(ys), INTERSECTION[1]))
    return x * y


def check() -> dict:
    root = ET.fromstring(road_xml())
    roads = {int(r.attrib["id"]): r for r in root.findall("road")}
    if set(roads) != {1, 2, 3, 4, 13, 14} or len(root.findall("junction/connection")) != 2:
        raise ValueError("Authored two-way intersection topology differs")
    if not all(roads[1].find("lanes/laneSection/right/lane[@id='-1']") is not None
               for _ in (0,)):
        raise ValueError("Inbound driving lane missing")
    out = {}
    for suffix in STOP_X:
        points = route(suffix)
        if any(abs(math.dist(a, b) - STEP_M) > 1e-8 for a, b in zip(points, points[1:])):
            raise ValueError("Route step discontinuity")
        footprint = body(*points[-1])
        overlap = overlap_area_xy(footprint)
        if suffix == "probe_a" and overlap != 0:
            raise ValueError("Outside probe enters intersection")
        if suffix == "probe_b" and overlap < 10:
            raise ValueError("Inside probe lacks a full-body overlap margin")
        out[suffix] = {"stop_center_xy_m": points[-1], "stop_body_xy_m": footprint,
                       "authored_intersection_overlap_m2": round(overlap, 5),
                       "route_points": len(points)}
    return {"passed": True, "law_id": "NRS-484B-450-1c", "cell_id": "C110454",
            "comparison_variable": "intersection_parking_footprint",
            "scope": "authored OpenDRIVE and prospective 5.2 x 2.2 m body only",
            "native_or_legal_outcome_claimed": False, "probes": out}


if __name__ == "__main__":
    print(json.dumps(check(), indent=2))

"""Four concrete, law-preserving construction settings per parking probe."""
from __future__ import annotations
import hashlib
import json
from pathlib import Path

CASES = ("probe_a", "probe_b")
CANDIDATES = ("primary", "fallback1", "fallback2", "fallback3")
BASE = {"route_lookahead_m": 5.0, "parking_brake_margin_m": 3.5,
        "overview_fov_deg": 90.0, "rate_hz": 20, "duration_s": 24}
CHANGES = {"primary": {}, "fallback1": {"route_lookahead_m": 3.0},
           "fallback2": {"parking_brake_margin_m": 6.0},
           "fallback3": {"overview_fov_deg": 105.0}}
TRIGGERS = {
    "fallback1": {"metric": "max_cross_track_error_m", "op": ">", "threshold": 0.45,
                  "source": "original Native pose joined to surveyed lane and authored route"},
    "fallback2": {"metric": "mean_final_park_speed_m_s", "op": ">", "threshold": 0.2,
                  "source": "original Native velocity during final 2 s at the target footprint"},
    "fallback3": {"metric": "min_vehicle_pixel_margin_px", "op": "<", "threshold": 40,
                  "source": "decoded original synchronized overview video and body mask"},
}


def parameters(case: str, candidate: str) -> dict:
    if case not in CASES or candidate not in CANDIDATES:
        raise ValueError("Unknown case or construction")
    return {"case": case, "candidate": candidate, "knobs": BASE | CHANGES[candidate],
            "fallback_trigger": TRIGGERS.get(candidate),
            "source_status": "original Native and pixels pending"}


def controller_parameters(case: str, candidate: str):
    from controller import EngineeringKnobs
    spec = parameters(case, candidate)["knobs"]
    return EngineeringKnobs(lookahead_base_m=spec["route_lookahead_m"],
                            target_speed_mps=4.5, final_brake_mps2=1.5,
                            final_margin_m=spec["parking_brake_margin_m"])


def evaluate_trigger(candidate: str, source: Path, expected_sha256: str) -> bool:
    if candidate not in TRIGGERS:
        raise ValueError("Only fallback triggers are measurable")
    raw = source.read_bytes()
    if hashlib.sha256(raw).hexdigest() != expected_sha256:
        raise ValueError("Trigger source hash differs")
    record = json.loads(raw)
    if record.get("source_kind") != "original_native_and_video":
        raise ValueError("Trigger metric lacks original source provenance")
    trigger = TRIGGERS[candidate]
    value = record.get(trigger["metric"])
    if type(value) not in (int, float):
        raise ValueError("Missing measured trigger metric")
    return value > trigger["threshold"] if trigger["op"] == ">" else value < trigger["threshold"]
